	}
	fresh := ReportID(decoded)
	doc = strings.Replace(doc, `"reportId":"`+r.ReportID+`"`, `"reportId":"`+fresh+`"`, 1)
	if err := os.WriteFile(filepath.Join(dir, fresh+".json"), []byte(doc), 0o644); err != nil {
