	}
}

// --- 严格解码器的结构性错误仍归类为损坏（经由 LoadReport 验证）---

func TestDecodeStoredReportStructuralErrors(t *testing.T) {
	for _, doc := range []string{
		`null`,
		`[1,2]`,
		`{"rules": 1}`,
		`{"artifact": "x"}`,
		`{"rules": [1]}`,
		`{"reportId": 5}`,
		`{"rules": [{"requiresABI": "x"}]}`,
		`{"reportId":"x"} extra`,
		`{broken`,
	} {
		if _, err := decodeStoredReport([]byte(doc)); err == nil {
			t.Errorf("expected decode error for %q", doc)
		}
	}
}

