		t.Fatalf("output is not a report: %v\n%s", err, raw)
	}
	out := make([]map[string]string, 0, len(doc.Rules))
	for _, r := range doc.Rules {
		m := map[string]string{}
		for k, v := range r {
			if s, ok := v.(string); ok {
				m[k] = s
			}
		}
		out = append(out, m)
	}
	return out
